-- Mod-authored World Congress popup descriptions, pl_PL overlay.
-- Baseline in CivVAccess_CongressDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_MISSING"] = "Brak opisu dla tego obrazu."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_SPECIAL_SESSION_START_WORLD_CONGRESS"] =
    "Zgromadzenie w trakcie obrad, widziane z tyłu sali ponad głowami widowni. Z przodu delegaci siedzą przy długim stole przykrytym czerwonym suknem na wyłożonym dywanami podium, przy każdym miejscu leży biała kartka papieru. Postać w białych szatach i białym nakryciu głowy stoi na czele stołu, by przemówić do sali, z ciemnobrodym mężczyzną u boku. Widownia słucha z rzędów drewnianych krzeseł, turbany i czapeczki obok odkrytych głów. Przy bladych kolumnach wzdłuż prawej ściany obserwują scenę dalsi widzowie."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_FAIR"] =
    "Ogromne koło Ferrisa pnie się ponad górną krawędź obrazu po prawej, z zamkniętymi kabinami dla pasażerów zwisającymi z obręcza. Jego podstawa schodzi za wielkim łukiem z zielonego nitowanego żelaza, rozpiętym nad bladą ścianą z napisem FERRIS WHEEL. Pod spodem goście wystawy przemierzają szeroką, zakurzoną promenadę: kobiety w długich sukniach, mężczyźni w płaszczach, melonikach i cylindrach. Wzdłuż drogi po lewej ciągną się niskie budynki wystawowe z malowanymi szyldami, a w głębi biały kopulasty gmach wznosi się w oddali pod bladoniebieskim niebem."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_GAMES"] =
    "Pierwsze kroki biegu: czterej zawodnicy odpychają się od linii startowej z pochylonymi głowami, na ciemnej bieżni wijącej się przez pierwszy plan. Za nimi po lewej stoi starter w długim białym płaszczu, z pistoletem uniesionym i wciąż dymiącym. Zapełnione trybuny zajmują całe tło, tłum zaznaczony plamkami koloru. Wzdłuż bieżni po prawej ciągną się białe stalowe trybuny i wysokie maszty, a zielone pole wewnętrzne rozciąga się za nimi w dal."
